UPDATE tenant
SET name = #{name},
    contact = #{contact},
    status = #{status}
WHERE id = #{id}

UPDATE tenant
SET status = #{status}
WHERE id = #{id}

mapper.select:
SELECT FROM tenant
status = #{status}
ORDER BY id ASC

SELECT FROM tenant
(name LIKE CONCAT('%', #{keyword}, '%') OR contact LIKE CONCAT('%', #{keyword}, '%'))
AND status = #{status}
ORDER BY id ASC LIMIT #{size} OFFSET #{offset}

SELECT t.id, t.name, t.contact, t.status, t.created_at, CASE WHEN t.id = 0 THEN 'PROFESSIONAL' ELSE COALESCE(l.edition, 'NONE') END AS license_edition, CASE WHEN t.id = 0 THEN 'EFFECTIVE' WHEN l.id IS NULL THEN 'NONE' ELSE 'EFFECTIVE' END AS license_status FROM tenant t LEFT JOIN license l ON l.id = ( SELECT li.id FROM license li WHERE li.tenant_id = t.id AND li.status = 1 AND li.expire_time > NOW() ORDER BY li.id DESC LIMIT 1 )
(t.name LIKE CONCAT('%', #{keyword}, '%') OR t.contact LIKE CONCAT('%', #{keyword}, '%'))
AND t.status = #{status}
ORDER BY t.id ASC LIMIT #{size} OFFSET #{offset}

SELECT COUNT(1) FROM tenant
(name LIKE CONCAT('%', #{keyword}, '%') OR contact LIKE CONCAT('%', #{keyword}, '%'))
AND status = #{status}
